// The census keeps the entries of unchanged tracked files, so a re-map does not stat or open them (#88).
import assert from 'node:assert/strict';
import { after, test } from 'node:test';
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import * as K from '../../helpers/kernel.mjs';
import { census } from '../../../runtime/graph/census.mjs';
import { mapRepository } from '../../../runtime/graph/builder.mjs';

after(() => K.cleanup());

const files = {
  'src/app.ts': 'export const a = 1;\n',
  'src/gen.ts': '// Code generated by a tool. DO NOT EDIT.\nexport const g = 1;\n',
  'src/app.test.ts': "import { a } from './app';\n",
  'docs/guide.md': '# Guide\n',
  'img/logo.png': 'not really a png\n',
};

/** An in-memory cache with the census's interface; counts what it was given. */
function memCache() {
  const rows = new Map();
  return {
    saved: 0,
    load: (key) => new Map([...rows].filter(([, r]) => r.key === key).map(([p, r]) => [p, r.entry])),
    save(key, entries) {
      this.saved += entries.length;
      for (const e of entries) rows.set(e.path, { key, entry: { ...e } });
    },
  };
}

const plain = (files) => files.map((f) => ({ ...f })).sort((a, b) => (a.path < b.path ? -1 : 1));

test('a census with a cache gives the entries of a census without one, and reuses every unchanged tracked file', () => {
  const p = K.makeProject({ files });
  const config = K.cfg();
  const cache = memCache();
  const first = census(p.dir, { config, cache });
  assert.equal(first.cached, 0);
  assert.ok(cache.saved >= Object.keys(files).length);
  const again = census(p.dir, { config, cache });
  assert.equal(again.cached, again.files.length, 'every tracked, unchanged file comes from the cache');
  const none = census(p.dir, { config });
  assert.deepEqual(plain(again.files), plain(none.files));
  assert.deepEqual(again.byKind, none.byKind);
  assert.equal(none.files.find((f) => f.path === 'src/gen.ts').kind, 'generated');

  // An uncommitted edit is read again; a committed one has a new blob and is read again too.
  writeFileSync(join(p.dir, 'src/app.ts'), '// @generated\nexport const a = 2;\n');
  const edited = census(p.dir, { config, cache });
  assert.equal(edited.cached, edited.files.length - 1);
  assert.equal(edited.files.find((f) => f.path === 'src/app.ts').kind, 'generated');
  assert.equal(edited.files.find((f) => f.path === 'src/app.ts').blob, null, 'a modified file has no git blob');
  K.git(p.dir, 'add', '-A');
  K.git(p.dir, 'commit', '-q', '-m', 'edit');
  const committed = census(p.dir, { config, cache });
  assert.equal(committed.cached, committed.files.length - 1);
  assert.deepEqual(plain(committed.files), plain(census(p.dir, { config }).files));

  // Rules the path alone does not show (a configured generated path) classify every file again.
  const other = K.cfg({ generated_paths: ['docs/**'] });
  const reclassified = census(p.dir, { config: other, cache });
  assert.equal(reclassified.cached, 0);
  assert.equal(reclassified.files.find((f) => f.path === 'docs/guide.md').kind, 'generated');
});

test('a map keeps census entries in the store and a re-map classifies nothing again', async () => {
  const p = K.makeProject({ files });
  const config = K.cfg({ mode: 'plan' });
  await mapRepository(p.ctx, { config, configDigest: 'd', history: false });
  const rows = p.ctx.store.get("SELECT COUNT(*) AS n FROM file_index WHERE adapter = 'census:entry'").n;
  assert.ok(rows >= Object.keys(files).length);
  writeFileSync(join(p.dir, 'src/app.ts'), 'export const a = 3;\n');
  K.git(p.dir, 'commit', '-q', '-am', 'edit');
  const r = await mapRepository(p.ctx, { config, configDigest: 'd', history: false });
  assert.equal(r.census.cached, r.census.files - 1, 'only the edited file is stat\'ed and read');
});
